        function setCookie(name, value, maxAgeMs) {
          const segments = [
            name + '=' + encodeURIComponent(value),
            'expires=' + new Date(Date.now() + maxAgeMs).toUTCString(),
            'path=/',
            'SameSite=Lax',
          ];
          const domain = getCookieDomain();
          if (domain) {
            segments.push('domain=' + domain);
          }
          document.cookie = segments.join('; ');
