          if (!callbackName) {
            return null;
          }
          const parts = `${callbackName}`.split('.').filter(Boolean);
          let target = window;
          if (parts[0] === 'window') {
            parts.shift();
          }
          for (const part of parts) {
            target = target && target[part];
