        function getH5AttributionBridgeData() {
          const queryData = getQueryH5AttributionBridgeData();
          if (queryData) {
            try {
              localStorage.setItem(H5_ATTRIBUTION_BRIDGE_STORAGE_KEY, JSON.stringify(queryData));
            } catch (error) {}
            return queryData;
          }
          return getStoredH5AttributionBridgeData();
        }

        function setOptionalStorageValue(key, value) {
          const normalized = `${value || ''}`.trim();
          if (normalized) {
